//catalog.марки | проект_заказ ($h.проект_заказ) | Select (id, title) 

var result = await from('catalog.марки')
  .select([
    'title as text',
    'id as value'
  ])
  .where('проект_заказ = @project')
  .parameter('project', $h.проект_заказ, 11)
  .query();

return result;

